"""Actual entrepreneurial construction, escrow, licensing and provider inspection."""
from test_mobile_rendering import ROOT,html
from playwright.sync_api import sync_playwright
import json,hashlib,os
kind=os.environ.get("TOWNLEDGER_TEST_PROVIDER","school")
source=(ROOT/'assets/game.js').read_text();sha=hashlib.sha256(source.encode()).hexdigest()
probe=r'''
window.__serviceEntrySetup=()=>{__townTest.reset('settlement',42);G.autoBuild=false;G.policy.privateServices=1;G.policy.educationBudget=0;G.policy.defenseBudget=0;G.policy.serviceVoucherBudget=100;for(const p of G.people)if(p.age>=18&&p.age<=60)p.skill=.6;G.policy.privateTuitionCap=4;G.policy.privateFireFeeCap=1;return totalMoney()};
window.__serviceEntryCheck=()=>({total:totalMoney(),pending:G.projects.filter(p=>p.privateService).map(p=>({kind:p.privateService,escrow:p.serviceEscrow,remaining:p.remaining})),providers:G.firms.filter(f=>f.privateService).map(f=>({id:f.id,kind:f.privateService,clients:f.clientsToday,staff:f.workers.length,cash:f.cash,closed:f.closed,owner:f.owner,publicFacility:isPublicFacility(readBuild(f.building))})),valid:validateTown()});
window.__serviceLicenseOff=()=>{G.policy.privateServices=0;return seekPrivateServiceInvestment('fire')};
'''
with sync_playwright() as pw:
 b=pw.chromium.launch(executable_path='/usr/bin/chromium',args=['--no-sandbox']);p=b.new_page(viewport={'width':844,'height':390},has_touch=True);errors=[];p.on('pageerror',lambda e:errors.append(str(e)));p.set_content(html);p.add_script_tag(content=source.replace('// SOURCE: 99-instrumentation.js',probe+'\n// SOURCE: 99-instrumentation.js'));p.locator('#newTown').click();p.locator('#pause').click();p.locator('#panelClose').click();total=p.evaluate('__serviceEntrySetup()');p.locator('[data-panel=community]').click();p.locator('[data-private-invite='+kind+']').click();r=p.evaluate('__serviceEntryCheck()');assert r['pending'] and r['pending'][0]['escrow']==6000,r;assert abs(r['total']-total)<.001 and r['valid']['ok'],r;save=p.evaluate('__townTest.save()');bad=json.loads(save);del bad['projects'][0]['privateService'];assert not p.evaluate('s=>__townTest.load(s)',json.dumps(bad));assert p.evaluate('s=>__townTest.load(s)',save);assert abs(p.evaluate('__serviceEntryCheck().total')-total)<.001
 p.keyboard.press('Escape');p.locator('[data-panel=community]').click();p.locator('#privateServicePolicies').click();assert p.locator('#privatePolicyGroup').evaluate('(e)=>e.open');p.locator('input[data-policy=serviceVoucherBudget]').fill('80');p.locator('#enactPolicy').click();assert p.evaluate('__townTest.get().policy.serviceVoucherBudget')==80;p.locator('#panelClose').click();p.evaluate('__townTest.step(110)');r=p.evaluate('__serviceEntryCheck()');assert r['providers'] and r['providers'][0]['staff']>0 and r['providers'][0]['clients']>0,r;assert not r['providers'][0]['publicFacility'] and r['providers'][0]['owner']==-1;assert r['valid']['ok'] and abs(r['total']-total)<.001,r;assert 'not licensed' in p.evaluate('__serviceLicenseOff()');p.locator('[data-panel=community]').click();out=ROOT/'reports/development-8.0';out.mkdir(exist_ok=True);p.screenshot(path=str(out/('independent-'+kind+'.png')));assert not errors,errors;b.close()
assert hashlib.sha256((ROOT/'assets/game.js').read_bytes()).hexdigest()==sha
(out/('private-service-entry-'+kind+'.json')).write_text(json.dumps({'source_sha256':sha,'result':r,'cashDrift':r['total']-total,'errors':errors},indent=2)+'\n');print('PASS actual provider invitation, private capital/escrow, construction, qualified staffing, fee clients, staged vouchers, licensing and conservation',r)
